import openings from './openings.json'

// Generated by scripts/build-openings.js from lichess chess-openings (CC0).
const BOOK = new Set<string>(openings)

/** Whether a position lies on a named opening line. Move clocks are ignored. */
export function isBookPosition(fen: string): boolean {
  return BOOK.has(fen.split(' ').slice(0, 4).join(' '))
}
